-- 0170: per-tech travel radius. technicians.service_zips (null = whole service
-- area, the behavior every existing tech keeps). tech_invites.service_zips is
-- copied onto the technician row when the invite is claimed (api/tech.js joinComplete).
-- Lists are Census 2023 ZCTA centroids within N miles (haversine).
alter table app.technicians  add column if not exists service_zips text[];
alter table app.tech_invites add column if not exists service_zips text[];

-- Dominic Urban (OKC), home 73112, 20 mi: 60 zips.
